    const REMEDY_WORDS = ['remedy', 'remedies', 'pariharam', 'parikaram', 'parihara', 'mantra', 'temple', 'pooja', 'puja', 'prayer', 'fasting', 'charity',
        'பரிகாரம்', 'மந்திரம்', 'கோயில்', 'கோவில்', 'பூஜை', 'விரதம்', 'தானம்', 'उपाय', 'मंत्र', 'मंदिर', 'पूजा', 'व्रत', 'दान'];

    const TIMING_WORDS = ['when', 'which year', 'how long', 'what time', 'எப்போது', 'எப்பொழுது', 'எந்த வருடம்', 'எவ்வளவு காலம்', 'कब', 'किस साल', 'कितने समय'];

