                'Order status: COMPLETED' => 'ஆர்டர் நிலை: முடிந்தது',
                'Order status: PROCESSING' => 'ஆர்டர் நிலை: செயலாக்கத்தில்',
                'Order status:' => 'ஆர்டர் நிலை:',
                'Answering for:' => 'யாருக்கான பதில்:',
